#!/usr/bin/env python3  # Execute this one-shot Pareto-gate finalizer with the repository interpreter.
"""Compare WM-VLA and Dörfler through best-so-far two-resource envelopes."""  # State the exact scientific correction applied by this temporary script.

from __future__ import annotations  # Enable postponed annotation evaluation.

from pathlib import Path  # Import portable repository-path handling.


def main() -> None:  # Replace the raw-point gate and append deterministic regression tests.
    root = Path(__file__).resolve().parents[1]  # Resolve the checked-out repository root.
    campaign = root / "scripts" / "run_world_model_vla_bridge.py"  # Select the held-out campaign source.
    text = campaign.read_text(encoding="utf-8")  # Read the exact branch source.
    start = text.index("def compare_to_dorfler(")  # Locate the current comparison function.
    end = text.index("\n\ndef _case_problem", start)  # Locate the next stable campaign function.
    replacement = '''def compare_to_dorfler(dorfler: list[dict[str, Any]], world: list[dict[str, Any]], tolerance: float = 1.0e-8) -> dict[str, Any]:  # Test best-so-far Pareto envelopes in solves and equations.\n    if not dorfler or not world:  # Reject an empty physical trajectory.\n        return {"not_weaker": False, "reason": "empty_trajectory", "checks": [], "best_gain": float("nan"), "solve_saving": 0}  # Report a failed comparison contract.\n    metric_names = {point["metric_name"] for point in dorfler + world}  # Read all available comparison metric types.\n    if len(metric_names) != 1:  # Require the same reference or estimator metric across both methods.\n        return {"not_weaker": False, "reason": "metric_mismatch", "checks": [], "best_gain": float("nan"), "solve_saving": 0}  # Reject mixed evidence levels.\n    checks: list[dict[str, Any]] = []  # Allocate two-resource Pareto-envelope checks.\n    for threshold in world:  # Use every realized WM-VLA resource rectangle as an acceptance threshold.\n        world_admissible = [point for point in world if point["solve"] <= threshold["solve"] and point["n_equations"] <= threshold["n_equations"]]  # Retain WM-VLA points reachable within the rectangle.\n        dorfler_admissible = [point for point in dorfler if point["solve"] <= threshold["solve"] and point["n_equations"] <= threshold["n_equations"]]  # Retain Dörfler points reachable within the same rectangle.\n        if not dorfler_admissible:  # Handle a rectangle containing no classical baseline point.\n            checks.append({"threshold": threshold, "world_best": min(world_admissible, key=lambda point: point["metric"]), "dorfler_best": None, "pass": True, "reason": "no_dorfler_point_in_resource_rectangle"})  # Record the vacuous baseline comparison explicitly.\n            continue  # Evaluate the next realized resource rectangle.\n        world_best = min(world_admissible, key=lambda point: point["metric"])  # Select WM-VLA's best retained solution inside the rectangle.\n        dorfler_best = min(dorfler_admissible, key=lambda point: point["metric"])  # Select Dörfler's best retained solution inside the rectangle.\n        passed = world_best["metric"] <= dorfler_best["metric"] * (1.0 + tolerance)  # Enforce the non-weaker Pareto-envelope floor.\n        checks.append({"threshold": threshold, "world_best": world_best, "dorfler_best": dorfler_best, "pass": bool(passed), "ratio": float(world_best["metric"] / max(dorfler_best["metric"], 1.0e-30))})  # Preserve the quantitative envelope check.\n    dorfler_final = min(point["metric"] for point in dorfler)  # Read the best baseline metric under the common campaign cap.\n    world_final = min(point["metric"] for point in world)  # Read the best world-model metric under the common campaign cap.\n    best_gain = (dorfler_final - world_final) / max(dorfler_final, 1.0e-30)  # Compute the relative final best-so-far improvement.\n    world_target_solve = min((point["solve"] for point in world if point["metric"] <= dorfler_final * (1.0 + tolerance)), default=len(world) + 1)  # Find when WM-VLA first reaches the baseline's final quality.\n    dorfler_target_solve = min((point["solve"] for point in dorfler if point["metric"] <= dorfler_final * (1.0 + tolerance)), default=len(dorfler))  # Find when Dörfler reaches its own final quality.\n    solve_saving = max(int(dorfler_target_solve - world_target_solve), 0)  # Quantify reduced sequential physical feedback rounds.\n    not_weaker = all(bool(check["pass"]) for check in checks) and world_final <= dorfler_final * (1.0 + tolerance)  # Require the complete two-resource envelope and final best point.\n    return {"not_weaker": bool(not_weaker), "reason": "ok" if not_weaker else "dorfler_floor_failed", "checks": checks, "best_gain": float(best_gain), "solve_saving": int(solve_saving), "world_advantage": bool(not_weaker and (best_gain > 0.02 or solve_saving >= 1))}  # Return the complete scientific comparison.\n'''
    text = text[:start] + replacement + text[end:]  # Replace only the Dörfler comparison function.
    campaign.write_text(text, encoding="utf-8")  # Write the corrected held-out campaign source.
    tests = root / "tests" / "test_world_controller.py"  # Select the focused WM-VLA unit suite.
    test_text = tests.read_text(encoding="utf-8")  # Read the exact branch test source.
    import_line = "from visionamr.vla.world_controller import plan_action  # Import the finite-horizon planner.\n"  # Identify the stable test import insertion point.
    additional_imports = "from importlib.util import module_from_spec  # Import dynamic module construction for the campaign-script test.\nfrom importlib.util import spec_from_file_location  # Import path-based module loading for the campaign-script test.\nfrom pathlib import Path  # Import portable repository-path resolution for the campaign-script test.\n"  # Define the standard-library test imports.
    if additional_imports not in test_text:  # Insert the campaign loader dependencies only once.
        if import_line not in test_text:  # Reject an incompatible unit-suite revision.
            raise RuntimeError("world-controller test import marker was not found")  # Stop before a speculative edit.
        test_text = test_text.replace(import_line, import_line + additional_imports, 1)  # Add the loader imports after controller imports.
    test_block = '''\n\ndef _campaign_module():  # Load the executable campaign script without turning scripts into a package.\n    path = Path(__file__).resolve().parents[1] / "scripts" / "run_world_model_vla_bridge.py"  # Resolve the canonical campaign script.\n    spec = spec_from_file_location("run_world_model_vla_bridge_test", path)  # Build a path-based import specification.\n    assert spec is not None and spec.loader is not None  # Require a valid executable module specification.\n    module = module_from_spec(spec)  # Construct the isolated campaign module.\n    spec.loader.exec_module(module)  # Execute its definitions without launching main().\n    return module  # Return the loaded comparison surface.\n\n\ndef test_dorfler_floor_uses_best_so_far_pareto_envelopes() -> None:  # Verify that dominated raw remeshing points do not erase a retained superior solution.\n    campaign = _campaign_module()  # Load the executable comparison function.\n    dorfler = [{"solve": 1, "n_equations": 100, "metric_name": "energy_error", "metric": 1.0}, {"solve": 2, "n_equations": 200, "metric_name": "energy_error", "metric": 0.70}]  # Build a monotonically improving classical trajectory.\n    world = [{"solve": 1, "n_equations": 100, "metric_name": "energy_error", "metric": 1.0}, {"solve": 2, "n_equations": 220, "metric_name": "energy_error", "metric": 0.60}, {"solve": 3, "n_equations": 260, "metric_name": "energy_error", "metric": 0.66}]  # Add a later raw remesh regression dominated by the prior world solution.\n    comparison = campaign.compare_to_dorfler(dorfler, world)  # Compare retained solutions under two resource bounds.\n    assert comparison["not_weaker"]  # Require the best-so-far world envelope to retain its earlier superior solution.\n    assert comparison["world_advantage"]  # Require the measured ten-percent final improvement to count as world-model value.\n\n\ndef test_dorfler_floor_rejects_a_truly_weaker_envelope() -> None:  # Verify that best-so-far accounting cannot hide a method that never reaches Dörfler quality.\n    campaign = _campaign_module()  # Load the executable comparison function.\n    dorfler = [{"solve": 1, "n_equations": 100, "metric_name": "energy_error", "metric": 1.0}, {"solve": 2, "n_equations": 200, "metric_name": "energy_error", "metric": 0.70}]  # Build the classical reference trajectory.\n    world = [{"solve": 1, "n_equations": 100, "metric_name": "energy_error", "metric": 1.0}, {"solve": 2, "n_equations": 220, "metric_name": "energy_error", "metric": 0.82}]  # Build a world trajectory that remains physically weaker.\n    comparison = campaign.compare_to_dorfler(dorfler, world)  # Compare both best-so-far envelopes.\n    assert not comparison["not_weaker"]  # Require rejection of a genuinely weaker world-model method.\n    assert not comparison["world_advantage"]  # Forbid a false world-model advantage claim.\n'''
    if "def test_dorfler_floor_uses_best_so_far_pareto_envelopes" not in test_text:  # Append the two regression tests only once.
        test_text += test_block  # Extend the focused unit suite with Pareto-envelope gates.
    tests.write_text(test_text, encoding="utf-8")  # Write the corrected focused test suite.


if __name__ == "__main__":  # Execute only when launched as the one-shot finalizer.
    main()  # Apply the deterministic Pareto-gate correction.
